/**
 * @name Log Injection
 * @description User-controlled data in log messages can allow for log forging.
 * @kind path-problem
 * @problem.severity warning
 * @id py/log-injection
 * @tags security
 *       external/cwe/cwe-117
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module LogInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("logging").getMember(["info", "warning", "error", "critical", "debug", "log", "exception"]).getACall() |
      sink = call.getArg(0) or sink = call.getArgByName("msg")
    )
  }
}

module LogInjectionFlow = TaintTracking::Global<LogInjectionConfig>;
import LogInjectionFlow::PathGraph

from LogInjectionFlow::PathNode source, LogInjectionFlow::PathNode sink
where LogInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Log injection from $@.", source.getNode(), "user input"

/**
 * @name HTTP Header Injection
 * @description Writing user input directly to HTTP headers can allow for Header Injection or Response Splitting.
 * @kind path-problem
 * @problem.severity error
 * @id py/header-injection
 * @tags security
 *       external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("fastapi").getMember("Response").getACall() or
      call = API::moduleImport("fastapi.responses").getMember(["JSONResponse", "HTMLResponse", "PlainTextResponse", "Response"]).getACall() or
      call = API::moduleImport("starlette.responses").getMember(["JSONResponse", "HTMLResponse", "PlainTextResponse", "Response"]).getACall() |
      // Headers are usually passed as a dict to the 'headers' argument
      // We look for flow into that dictionary or the argument itself
      sink = call.getArgByName("headers")
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential HTTP header injection from $@.", source.getNode(), "user input"

/**
 * @name Improper modification of dynamic attributes
 * @description Modifying object attributes with user-controlled names can lead to unexpected behavior or security issues.
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-reflection
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UnsafeReflectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1) // The attribute name argument
    )
  }
}

module UnsafeReflectionFlow = TaintTracking::Global<UnsafeReflectionConfig>;
import UnsafeReflectionFlow::PathGraph

from UnsafeReflectionFlow::PathNode source, UnsafeReflectionFlow::PathNode sink
where UnsafeReflectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe attribute modification from $@.", source.getNode(), "user input"
